"""Generate the trajectory store (P2.4).

A trajectory is one complete verification, stored so that later runs can retrieve it as
experience. These are what ExpRAG fine-tunes on, what the FAISS store indexes, and what
the memory-poisoning study (C1) injects fakes into -- so this is the data the second half
of the project rests on.

**Generated by CRAG itself, not a throwaway agent.** The plan called for a v0 agent with
cross-encoder grades, built only to produce trajectories before the real pipeline
existed. The real pipeline exists now and is better, so trajectories come from it
directly. That also removes the re-grading step the plan needed to reconcile the two.

Successes and failures are written separately. Only verifications that matched the gold
label are fit to be SFT targets -- training on a wrong verdict teaches the wrong verdict
-- but failures are kept, because the error analysis needs them and because a failure is
still a legitimate thing to *retrieve* as experience ("this approach did not work here").

    python -m experience.generate --data data/averitec/train.json \
        --store data/averitec/pool_train_full.jsonl \
        --evaluator results/<date>_t5-evaluator/model --limit 1500
"""

from __future__ import annotations

import argparse
import json
from collections.abc import Sequence
from pathlib import Path
from typing import Any

from agent.crag import crag
from core.config import RunConfig
from core.llm import LLMClient
from core.paths import DATA_DIR, run_dir
from eval.datasets import load_averitec, sample
from eval.metrics import score as score_metrics
from evaluator.score import load_scorer
from experience.format import Trajectory, write_jsonl
from retrieval.store import open_store

SECONDS_PER_CLAIM = 12  # measured on a T4 with qwen2.5:7b; used only for the warning


def summarise(trajectories: Sequence[Trajectory]) -> dict[str, Any]:
    labelled = [t for t in trajectories if t.gold_label]
    actions: dict[str, int] = {}
    for t in trajectories:
        actions[t.action or "none"] = actions.get(t.action or "none", 0) + 1
    out: dict[str, Any] = {
        "total": len(trajectories),
        "correct": sum(1 for t in trajectories if t.correct),
        "incorrect": sum(1 for t in trajectories if t.correct is False),
        "unlabelled": len(trajectories) - len(labelled),
        "action_share": {k: round(v / max(len(trajectories), 1), 3) for k, v in actions.items()},
        "unparseable": sum(1 for t in trajectories if not t.metadata.get("parsed", True)),
        "mean_evidence": round(
            sum(len(t.evidence) for t in trajectories) / max(len(trajectories), 1), 2
        ),
    }
    if labelled:
        m = score_metrics([t.gold_label for t in labelled], [t.verdict for t in labelled])
        out["macro_f1"] = m.macro_f1
        out["accuracy"] = m.accuracy
    return out


def main(argv: list[str] | None = None) -> int:
    p = argparse.ArgumentParser(prog="python -m experience.generate")
    p.add_argument("--data", type=Path, required=True, help="AVeriTeC split (use train.json)")
    p.add_argument("--store", type=Path, required=True)
    p.add_argument("--evaluator", type=Path, default=None)
    p.add_argument("--out", type=Path, default=DATA_DIR / "trajectories")
    p.add_argument("--limit", type=int, default=None)
    p.add_argument("--seed", type=int, default=13)
    p.add_argument("--name", default="trajectories")
    p.add_argument("--dry-run", action="store_true")
    args = p.parse_args(argv)

    if args.data.stem == "dev":
        print(
            "[verimem] WARNING: generating trajectories from dev. These become training "
            "data and retrievable experience, so the system would meet its own test set "
            "(rule 5). Use train.json."
        )
    if args.evaluator is None:
        print(
            "[verimem] WARNING: no --evaluator, so grading falls back to a lexical stub. "
            "Trajectories generated this way are not the pipeline's real behaviour."
        )

    claims = sample(load_averitec(args.data, args.data.stem), args.limit, args.seed)
    source = open_store(args.store)
    with_evidence = [c for c in claims if source.has(str(c.id))]
    llm = LLMClient()
    cfg = RunConfig(split=args.data.stem, limit=args.limit, seed=args.seed)
    cfg.api_model, cfg.api_base_url = llm.model, llm.base_url

    print(f"[verimem] {len(claims)} claims, store has documents for {len(with_evidence)}")
    print(
        f"[verimem] thresholds: upper={cfg.crag_upper_threshold} lower={cfg.crag_lower_threshold}"
    )
    print(f"[verimem] up to ~{len(claims) * SECONDS_PER_CLAIM / 3600:.1f} h if nothing is cached")
    if args.dry_run:
        print("[verimem] --dry-run: nothing generated.")
        return 0

    scorer = load_scorer(args.evaluator)
    out_dir = run_dir(args.name)
    cfg.save(out_dir)

    trajectories: list[Trajectory] = []
    for i, claim in enumerate(claims, start=1):
        try:
            trajectories.append(crag(claim, llm, source, scorer, cfg))
        except Exception as exc:  # noqa: BLE001
            if "Connection" not in type(exc).__name__ and "Connection" not in str(exc):
                raise
            raise SystemExit(
                f"\nThe endpoint stopped responding at claim {i}/{len(claims)}.\\n"
                f"  {i - 1} trajectories are cached and replay instantly.\n"
                f"  Restart the endpoint and run the same command to resume."
            ) from exc
        if i % 25 == 0 or i == len(claims):
            kept = sum(1 for t in trajectories if t.correct)
            print(f"  [{i}/{len(claims)}] {kept} correct so far", flush=True)

    # Successes and failures live apart: only the former are fit to be SFT targets.
    args.out.mkdir(parents=True, exist_ok=True)
    good = [t for t in trajectories if t.correct is not False]
    bad = [t for t in trajectories if t.correct is False]
    write_jsonl(good, args.out / "trajectories.jsonl")
    write_jsonl(bad, args.out / "trajectories_failed.jsonl")
    write_jsonl(trajectories, out_dir / "all_trajectories.jsonl")

    stats = summarise(trajectories)
    (out_dir / "metrics.json").write_text(json.dumps(stats, indent=2), encoding="utf-8")
    print(f"\n[verimem] {json.dumps(stats, indent=2)}")
    print(f"[verimem] {len(good)} usable -> {args.out}/trajectories.jsonl")
    print(f"[verimem] {len(bad)} failures -> {args.out}/trajectories_failed.jsonl")
    print(f"[verimem] wrote {out_dir}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
